import { test, mock } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import {
  RATING_SCALE,
  notchChange,
  notchCalculator,
} from "../../src/ratings/notch.mjs";

const EXPECTED_SCALE = [
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-", "BBB+", "BBB", "BBB-",
  "BB+", "BB", "BB-", "B+", "B", "B-", "CCC+", "CCC", "CCC-",
];

const INVALID = ["", "   ", "BBB++", "D", "NR", "Baa1", "AAA+", "CCC--", "BBB +", "B B", null, undefined, 7, {}, [], true];
// the 15 values of the card plus `true`; extra look-alikes below
const LOOK_ALIKES = ["BBB−", "BBB–", "\t\n", "SD", "WR", "BBB+ (neg)", new String("AAA")];

const expectedWl = (n) => (n <= 1 ? 0 : n === 2 ? 1 : 2);
const expectedDirection = (n) => (n > 0 ? "downgrade" : n < 0 ? "upgrade" : "unchanged");

// AC-1
test("RATING_SCALE has the 19 ratings, best first, and is frozen", () => {
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test("RATING_SCALE rejects mutation with TypeError and stays unchanged", () => {
  assert.throws(() => RATING_SCALE.push("D"), TypeError);
  assert.throws(() => {
    RATING_SCALE[0] = "X";
  }, TypeError);
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
});

// AC-2
test("notchChange returns index(current) - index(previous)", () => {
  assert.equal(notchChange("BBB+", "BB+"), 3);
  assert.equal(notchChange("BBB+", "BBB-"), 2);
  assert.equal(notchChange("BBB+", "BBB"), 1);
  assert.equal(notchChange("BB+", "BBB+"), -3);
  assert.equal(notchChange("AAA", "CCC-"), 18);
  assert.equal(notchChange("CCC-", "AAA"), -18);
});

test("notchChange of the same rating is +0, not -0", () => {
  assert.equal(Object.is(notchChange("A", "A"), 0), true);
  assert.equal(Object.is(notchChange("AAA", "AAA"), 0), true);
  assert.equal(Object.is(notchChange("CCC-", "CCC-"), 0), true);
});

test("notchChange gives an integer in -18..18 for all 361 pairs", () => {
  let count = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const r = notchChange(p, c);
      assert.equal(Number.isInteger(r), true, `${p}->${c}`);
      assert.ok(r >= -18 && r <= 18, `${p}->${c}`);
      assert.equal(r, EXPECTED_SCALE.indexOf(c) - EXPECTED_SCALE.indexOf(p));
      count++;
    }
  }
  assert.equal(count, 361);
});

// AC-3
test("notchChange ignores case and leading/trailing whitespace", () => {
  assert.equal(notchChange("bbb+", "BB+"), 3);
  assert.equal(notchChange("  BBB+ ", "\tbb+\n"), 3);
  assert.equal(notchChange(" aa-", "AA- "), 0);
  assert.equal(notchChange(" aa-", "AA- "), 0);
  assert.equal(notchChange("﻿aa-", "AA- "), 0);
});

test("notchCalculator ignores case and whitespace", () => {
  assert.deepStrictEqual(notchCalculator(" bBb+", "bbb- "), {
    notches: 2,
    direction: "downgrade",
    wl: 1,
  });
});

// AC-4
const FIFTEEN = INVALID.slice(0, 15);
for (const [name, fn] of [["notchChange", notchChange], ["notchCalculator", notchCalculator]]) {
  test(`${name} throws RangeError (never TypeError) for invalid previous`, () => {
    for (const bad of [...FIFTEEN, ...INVALID.slice(15), ...LOOK_ALIKES]) {
      assert.throws(() => fn(bad, "AAA"), RangeError, `previous=${String(bad)}`);
    }
  });
  test(`${name} throws RangeError (never TypeError) for invalid current`, () => {
    for (const bad of [...FIFTEEN, ...INVALID.slice(15), ...LOOK_ALIKES]) {
      assert.throws(() => fn("AAA", bad), RangeError, `current=${String(bad)}`);
    }
  });
  test(`${name} throws RangeError when both arguments are invalid`, () => {
    assert.throws(() => fn("D", "NR"), RangeError);
    assert.throws(() => fn(null, undefined), RangeError);
  });
  test(`${name} error message names the argument and the bad value`, () => {
    assert.throws(() => fn("XYZ", "AAA"), (e) => e instanceof RangeError && /previous/.test(e.message) && /XYZ/.test(e.message));
    assert.throws(() => fn("AAA", "XYZ"), (e) => e instanceof RangeError && /current/.test(e.message) && /XYZ/.test(e.message));
  });
}

test("invalid input never surfaces as TypeError", () => {
  for (const bad of [null, undefined, 7, {}, [], true, Symbol("x"), 10n, Object.create(null)]) {
    for (const fn of [notchChange, notchCalculator]) {
      for (const args of [[bad, "AAA"], ["AAA", bad]]) {
        try {
          fn(...args);
          assert.fail("expected throw");
        } catch (e) {
          assert.ok(e instanceof RangeError, `got ${e && e.constructor && e.constructor.name}`);
        }
      }
    }
  }
});

// AC-5..AC-8
test("notchCalculator BBB+ -> BB+ is 3 notches / WL 2 (C2) with exactly three keys", () => {
  const r = notchCalculator("BBB+", "BB+");
  assert.deepStrictEqual(r, { notches: 3, direction: "downgrade", wl: 2 });
  assert.deepStrictEqual(Object.keys(r).sort(), ["direction", "notches", "wl"]);
});

test("notchCalculator BBB+ -> BBB- is 2 notches / WL 1", () => {
  assert.deepStrictEqual(notchCalculator("BBB+", "BBB-"), { notches: 2, direction: "downgrade", wl: 1 });
});

test("notchCalculator downgrade thresholds", () => {
  assert.deepStrictEqual(notchCalculator("BBB+", "BBB"), { notches: 1, direction: "downgrade", wl: 0 });
  assert.deepStrictEqual(notchCalculator("A", "BBB+"), { notches: 2, direction: "downgrade", wl: 1 });
  assert.deepStrictEqual(notchCalculator("A", "BBB"), { notches: 3, direction: "downgrade", wl: 2 });
  assert.deepStrictEqual(notchCalculator("AAA", "CCC-"), { notches: 18, direction: "downgrade", wl: 2 });
});

test("notchCalculator upgrades have WL 0", () => {
  assert.deepStrictEqual(notchCalculator("BBB", "BBB+"), { notches: -1, direction: "upgrade", wl: 0 });
  assert.deepStrictEqual(notchCalculator("BB+", "BBB+"), { notches: -3, direction: "upgrade", wl: 0 });
  assert.deepStrictEqual(notchCalculator("CCC-", "AAA"), { notches: -18, direction: "upgrade", wl: 0 });
});

test("notchCalculator unchanged is notches +0, WL 0", () => {
  const unchanged = { notches: 0, direction: "unchanged", wl: 0 };
  assert.deepStrictEqual(notchCalculator("A", "a "), unchanged);
  assert.deepStrictEqual(notchCalculator("AAA", "AAA"), unchanged);
  assert.deepStrictEqual(notchCalculator("CCC-", "CCC-"), unchanged);
});

// AC-9
test("notchCalculator is consistent with notchChange for all 361 pairs", () => {
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const n = notchChange(p, c);
      const r = notchCalculator(p, c);
      assert.equal(r.notches, n, `${p}->${c}`);
      assert.equal(r.direction, expectedDirection(n), `${p}->${c}`);
      assert.equal(r.wl, expectedWl(n), `${p}->${c}`);
    }
  }
});

// AC-13
test("module exports exactly RATING_SCALE, notchCalculator and notchChange", async () => {
  const mod = await import("../../src/ratings/notch.mjs");
  assert.deepStrictEqual(Object.keys(mod).sort(), ["RATING_SCALE", "notchCalculator", "notchChange"]);
  assert.equal("default" in mod, false);
});

test("functions are synchronous and return plain values", () => {
  for (const r of [notchChange("BBB+", "BB+"), notchCalculator("BBB+", "BB+")]) {
    assert.equal(r instanceof Promise, false);
    assert.notEqual(typeof r?.then, "function");
  }
});

test("functions do not write to the console", () => {
  const mocks = ["log", "error", "warn"].map((m) => mock.method(console, m, () => {}));
  try {
    notchChange("BBB+", "BB+");
    notchCalculator("BBB+", "BB+");
    assert.throws(() => notchChange("D", "AAA"), RangeError);
    assert.throws(() => notchCalculator("AAA", null), RangeError);
    for (const m of mocks) assert.equal(m.mock.callCount(), 0);
  } finally {
    mock.restoreAll();
  }
});

test("repeated calls are stable and do not alter RATING_SCALE", () => {
  const a = notchCalculator("BBB+", "BB+");
  const b = notchCalculator("BBB+", "BB+");
  assert.deepStrictEqual(a, b);
  assert.notEqual(a, b);
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
});

test("source has no imports and no I/O or console use", () => {
  const src = readFileSync(fileURLToPath(new URL("../../src/ratings/notch.mjs", import.meta.url)), "utf8");
  assert.equal(/^\s*import\s/m.test(src), false);
  assert.equal(/\bimport\s*\(/.test(src), false);
  assert.equal(/\brequire\s*\(/.test(src), false);
  for (const mod of ["node:fs", "fs", "node:http", "node:https", "node:net", "node:child_process", "node:process"]) {
    assert.equal(src.includes(`"${mod}"`) || src.includes(`'${mod}'`), false, mod);
  }
  assert.equal(/\bconsole\./.test(src), false);
});
