+// Rating notch calculator (REQ-06-02). Pure and synchronous: no imports, no I/O, no logging.
+
+export const RATING_SCALE = Object.freeze([
+  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-", "BBB+", "BBB", "BBB-",
+  "BB+", "BB", "BB-", "B+", "B", "B-", "CCC+", "CCC", "CCC-",
+]);
+
+// Safe text for error messages: never throws (symbols, null-prototype objects).
+function describe(value) {
+  try {
+    return typeof value === "string" ? JSON.stringify(value) : String(value);
+  } catch {
+    return Object.prototype.toString.call(value);
+  }
+}
+
+// Shared validation (C1). The typeof check comes before trim() so non-strings
+// always give RangeError, never TypeError.
+function ratingIndex(value, name) {
+  if (typeof value === "string") {
+    const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
+    if (index !== -1) return index;
+  }
+  throw new RangeError(`${name} is not a rating on the 19-step scale: ${describe(value)}`);
+}
+
+// Positive = downgrade, negative = upgrade. Range -18..18.
+export function notchChange(previous, current) {
+  const previousIndex = ratingIndex(previous, "previous");
+  const currentIndex = ratingIndex(current, "current");
+  // `+ 0` turns a possible -0 into +0.
+  return currentIndex - previousIndex + 0;
+}
+
+// Ind. 13 thresholds (C2): n <= 1 -> WL 0, n === 2 -> WL 1, n >= 3 -> WL 2.
+export function notchCalculator(previous, current) {
+  const notches = notchChange(previous, current);
+  const direction = notches > 0 ? "downgrade" : notches < 0 ? "upgrade" : "unchanged";
+  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
+  return { notches, direction, wl };
+}
