  assert.equal(countryRatingChangeWl("ccc", "CCC-"), 1);
  assert.equal(countryRatingChangeWl(" bbb+ ", "\tbbb\n"), 1);
  assert.equal(countryRatingChangeWl(" aa", "a- "), 2);
  assert.equal(countryRatingChangeWl(" aa", "a- "), 2);
});

const INVALID = ["", "   ", "BBB++", "D", "NR", "Baa1", "AAA+", "CCC--", "BBB +", "B B",
  null, undefined, 7, {}, [], new String("AAA"), "AA−", "AA–"];

for (const [i, bad] of INVALID.entries()) {
  test(`AC-4: invalid value #${i} as previous throws RangeError`, () => {
    assert.throws(() => countryRatingChangeWl(bad, "AAA"), (e) => {
      assert.ok(e instanceof RangeError);
      assert.ok(!(e instanceof TypeError));
      return true;
    });
  });
  test(`AC-4: invalid value #${i} as current throws RangeError`, () => {
    assert.throws(() => countryRatingChangeWl("AAA", bad), (e) => {
      assert.ok(e instanceof RangeError);
      assert.ok(!(e instanceof TypeError));
      return true;
    });
  });
}

test("AC-4: the error comes from notchChange unchanged", () => {
  let fromIndicator;
  let fromNotch;
  try { countryRatingChangeWl("NR", "AAA"); } catch (e) { fromIndicator = e; }
  try { notchChange("NR", "AAA"); } catch (e) { fromNotch = e; }
