import { test, mock } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

const crUrl = new URL("../../../src/indicators/countryRating.mjs", import.meta.url);
const mod = await import(crUrl.href);
const { countryRatingChangeWl } = mod;
const { RATING_SCALE, notchChange, notchCalculator } = await import(
  new URL("../../../src/ratings/notch.mjs", import.meta.url).href
);

const INVALID = [
  "", "   ", "BBB++", "D", "NR", "Baa1", "AAA+", "CCC--", "BBB +", "B B",
  null, undefined, 7, {}, [],
];
const label = (v) => (v === undefined ? "undefined" : JSON.stringify(v));

// ---------- AC-3 (indicator part) ----------
test("AC-3: case and surrounding whitespace are tolerated: ('ccc','CCC-') === 1", () => {
  assert.equal(countryRatingChangeWl("ccc", "CCC-"), 1);
});
test("AC-3: (' bbb+ ','\\tbbb\\n') === 1", () => {
  assert.equal(countryRatingChangeWl(" bbb+ ", "\tbbb\n"), 1);
});
test("AC-3: (' aa','a- ') === 2", () => {
  assert.equal(countryRatingChangeWl(" aa", "a- "), 2);
});
test("AC-3 (X-trim): NBSP at either end is removed", () => {
  assert.equal(countryRatingChangeWl(" BBB+ ", " BBB"), 1);
});

// ---------- AC-4 (indicator part) ----------
for (const bad of INVALID) {
  test(`AC-4: invalid previous ${label(bad)} throws RangeError (not TypeError)`, () => {
    assert.throws(
      () => countryRatingChangeWl(bad, "AAA"),
      (e) => e instanceof RangeError && !(e instanceof TypeError),
    );
  });
  test(`AC-4: invalid current ${label(bad)} throws RangeError (not TypeError)`, () => {
    assert.throws(
      () => countryRatingChangeWl("AAA", bad),
      (e) => e instanceof RangeError && !(e instanceof TypeError),
    );
  });
}

test("AC-4: the error is the one notchChange throws, unchanged (same class, same message)", () => {
  for (const bad of INVALID) {
    let fromNotch;
    let fromWl;
    try { notchChange(bad, "AAA"); } catch (e) { fromNotch = e; }
    try { countryRatingChangeWl(bad, "AAA"); } catch (e) { fromWl = e; }
    assert.ok(fromNotch instanceof RangeError);
    assert.ok(fromWl instanceof RangeError);
    assert.equal(fromWl.constructor, fromNotch.constructor);
    assert.equal(fromWl.message, fromNotch.message);
  }
});

test("AC-4 edge: new String('AAA'), U+2212 and U+2013 minus look-alikes throw RangeError", () => {
  for (const bad of [new String("AAA"), "AA−", "AA–", "CCC−", "BBB–"]) {
    assert.throws(() => countryRatingChangeWl(bad, "AAA"), RangeError);
    assert.throws(() => countryRatingChangeWl("AAA", bad), RangeError);
  }
});

// ---------- AC-10 ----------
const DOWNGRADES = [
  ["BBB+", "BBB", 1],
  ["BBB+", "BBB-", 2],
  ["BBB+", "BB+", 2],
  ["AAA", "CCC-", 2],
  ["CCC", "CCC-", 1],
  ["AAA", "AA+", 1],
  ["AA", "A-", 2],
  ["AA", "AA-", 1],
];
for (const [p, c, wl] of DOWNGRADES) {
  test(`AC-10: ${p} -> ${c} gives WL ${wl}`, () => {
    assert.equal(countryRatingChangeWl(p, c), wl);
  });
}

// ---------- AC-11 ----------
for (const [p, c] of [["BBB", "BBB+"], ["CCC-", "AAA"], ["A", "A"], ["AAA", "AAA"], ["CCC-", "CCC-"]]) {
  test(`AC-11: ${p} -> ${c} (upgrade or unchanged) is strictly 0`, () => {
    const r = countryRatingChangeWl(p, c);
    assert.strictEqual(r, 0);
    assert.ok(Object.is(r, 0), "must not be -0");
  });
}

test("AC-10/AC-11: all 361 pairs: result in [0,1,2], 0 if n<=0, 1 if n===1, 2 if n>=2", () => {
  let count = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const n = notchChange(p, c);
      const r = countryRatingChangeWl(p, c);
      const expected = n <= 0 ? 0 : n === 1 ? 1 : 2;
      assert.ok([0, 1, 2].includes(r), `${p}->${c}: ${r} not in [0,1,2]`);
      assert.ok(Object.is(r, expected), `${p}->${c} (n=${n}): expected ${expected}, got ${r}`);
      count += 1;
    }
  }
  assert.equal(count, 361);
});

test("AC-10/AC-11 edge: n = -1, 0, 1, 2, 3, 18 fall in the right band", () => {
  const cases = [
    ["BBB", "BBB+", -1, 0],
    ["A", "A", 0, 0],
    ["BBB+", "BBB", 1, 1],
    ["BBB+", "BBB-", 2, 2],
    ["BBB+", "BB+", 3, 2],
    ["AAA", "CCC-", 18, 2],
  ];
  for (const [p, c, n, wl] of cases) {
    assert.equal(notchChange(p, c), n);
    assert.equal(countryRatingChangeWl(p, c), wl);
  }
});

// ---------- AC-11 contrast with Ind. 13 ----------
test("AC-11: ('BBB+','BBB') is 1 for Ind. 12 while notchCalculator().wl is 0 (different thresholds)", () => {
  assert.strictEqual(countryRatingChangeWl("BBB+", "BBB"), 1);
  assert.strictEqual(notchCalculator("BBB+", "BBB").wl, 0);
});

test("AC-11: contrast table: Ind. 12 vs notchCalculator().wl on spec test data", () => {
  const rows = [
    ["BBB+", "BBB", 1, 0],
    ["BBB+", "BBB-", 2, 1],
    ["BBB+", "BB+", 2, 2],
    ["AAA", "CCC-", 2, 2],
    ["CCC", "CCC-", 1, 0],
    ["AAA", "AA+", 1, 0],
    ["AA", "A-", 2, 2],
    ["AA", "AA-", 1, 0],
    ["BBB", "BBB+", 0, 0],
    ["CCC-", "AAA", 0, 0],
    ["A", "A", 0, 0],
  ];
  for (const [p, c, ind12, ind13] of rows) {
    assert.strictEqual(countryRatingChangeWl(p, c), ind12, `${p}->${c} Ind.12`);
    assert.strictEqual(notchCalculator(p, c).wl, ind13, `${p}->${c} Ind.13`);
  }
});

// ---------- AC-12 ----------
test("AC-12: edited current value is honoured and the original pair is unaffected afterwards", () => {
  assert.strictEqual(countryRatingChangeWl("AA", "A-"), 2);
  assert.strictEqual(countryRatingChangeWl("AA", "AA-"), 1);
  assert.strictEqual(countryRatingChangeWl("AA", "A-"), 2);
});

test("AC-12: interleaved calls in any order give identical results (no state)", () => {
  const pairs = [["AA", "A-", 2], ["BBB", "BBB+", 0], ["AA", "AA-", 1], ["CCC", "CCC-", 1], ["AAA", "CCC-", 2]];
  const expected = new Map(pairs.map(([p, c, w]) => [`${p}|${c}`, w]));
  const orders = [pairs, [...pairs].reverse(), [pairs[2], pairs[0], pairs[4], pairs[1], pairs[3], pairs[0], pairs[2]]];
  for (const order of orders) {
    for (const [p, c] of order) {
      assert.strictEqual(countryRatingChangeWl(p, c), expected.get(`${p}|${c}`));
    }
  }
});

test("AC-12: a failing call does not poison later calls", () => {
  assert.throws(() => countryRatingChangeWl("NR", "AAA"), RangeError);
  assert.strictEqual(countryRatingChangeWl("AA", "A-"), 2);
});

test("AC-12: signature takes exactly two parameters and ignores a third argument", () => {
  assert.equal(countryRatingChangeWl.length, 2);
  assert.strictEqual(countryRatingChangeWl("AA", "A-", "AA-"), 2);
});

// ---------- AC-13 (indicator part) ----------
test("AC-13: module exports exactly ['countryRatingChangeWl'] and no default export", () => {
  assert.deepStrictEqual(Object.keys(mod), ["countryRatingChangeWl"]);
  assert.equal("default" in mod, false);
  assert.equal(typeof mod.countryRatingChangeWl, "function");
});

test("AC-13: the only import is notchChange from ../ratings/notch.mjs; no I/O modules", () => {
  const src = readFileSync(crUrl, "utf8");
  const stripped = src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  const importStmts = stripped.match(/^\s*import\b[^;]*;?/gm) ?? [];
  assert.equal(importStmts.length, 1, `expected 1 import, found: ${JSON.stringify(importStmts)}`);
  assert.match(
    importStmts[0],
    /^\s*import\s*\{\s*notchChange\s*\}\s*from\s*(["'])\.\.\/ratings\/notch\.mjs\1\s*;?\s*$/,
  );
  assert.equal(/\bimport\s*\(/.test(stripped), false, "no dynamic import");
  assert.equal(/\brequire\s*\(/.test(stripped), false, "no require");
  for (const io of ["node:fs", "fs", "node:http", "node:https", "node:net", "node:child_process", "child_process", "http", "https", "net"]) {
    assert.equal(
      new RegExp(`(["'])${io.replace(":", ":")}\\1`).test(stripped),
      false,
      `must not reference ${io}`,
    );
  }
});

test("AC-13: valid input returns a plain number, not a Promise: ('BBB+','BB+') === 2", () => {
  const r = countryRatingChangeWl("BBB+", "BB+");
  assert.equal(r instanceof Promise, false);
  assert.notEqual(typeof r?.then, "function");
  assert.equal(typeof r, "number");
  assert.strictEqual(r, 2);
});

test("AC-13: invalid input throws synchronously (no rejected Promise)", () => {
  let returned;
  assert.throws(() => { returned = countryRatingChangeWl("NR", "AAA"); }, RangeError);
  assert.equal(returned, undefined);
});

test("AC-13: no console.log / console.error / console.warn output on valid or invalid input", () => {
  const log = mock.method(console, "log", () => {});
  const error = mock.method(console, "error", () => {});
  const warn = mock.method(console, "warn", () => {});
  try {
    countryRatingChangeWl("BBB+", "BB+");
    countryRatingChangeWl("A", "A");
    for (const bad of INVALID) {
      try { countryRatingChangeWl(bad, "AAA"); } catch { /* expected */ }
