    assert.equal(error.mock.callCount(), 0);
    assert.equal(warn.mock.callCount(), 0);
  } finally {
    mock.restoreAll();
  }
});

test("AC-13: calls write nothing to process.stdout / process.stderr", () => {
  const out = mock.method(process.stdout, "write", () => true);
  const err = mock.method(process.stderr, "write", () => true);
  let outCalls;
  let errCalls;
  try {
    countryRatingChangeWl("BBB+", "BB+");
    try { countryRatingChangeWl("NR", "AAA"); } catch { /* expected */ }
    outCalls = out.mock.callCount();
    errCalls = err.mock.callCount();
  } finally {
    mock.restoreAll();
  }
  assert.equal(outCalls, 0);
  assert.equal(errCalls, 0);
});

test("AC-13: src/indicators/countryRating.mjs does not use notchCalculator (Ind. 13 thresholds)", () => {
  const src = readFileSync(crUrl, "utf8");
  const stripped = src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  assert.equal(/notchCalculator/.test(stripped), false);
});

// ---------- AC-14 ----------
test("AC-14: package.json has no dependencies and no devDependencies", () => {
  const pkg = JSON.parse(readFileSync(new URL("../../../package.json", import.meta.url), "utf8"));
  assert.strictEqual(pkg.dependencies, undefined);
  assert.strictEqual(pkg.devDependencies, undefined);
});

