1	// Rating notch calculator (REQ-06-02). Pure and synchronous: no imports, no I/O, no logging.
2	
3	export const RATING_SCALE = Object.freeze([
4	  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-", "BBB+", "BBB", "BBB-",
5	  "BB+", "BB", "BB-", "B+", "B", "B-", "CCC+", "CCC", "CCC-",
6	]);
7	
8	// Safe text for error messages: never throws (symbols, null-prototype objects).
9	function describe(value) {
10	  try {
11	    return typeof value === "string" ? JSON.stringify(value) : String(value);
12	  } catch {
13	    return Object.prototype.toString.call(value);
14	  }
15	}
16	
17	// Shared validation (C1). The typeof check comes before trim() so non-strings
18	// always give RangeError, never TypeError.
19	function ratingIndex(value, name) {
20	  if (typeof value === "string") {
21	    const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
22	    if (index !== -1) return index;
23	  }
24	  throw new RangeError(`${name} is not a rating on the 19-step scale: ${describe(value)}`);
25	}
26	
27	// Positive = downgrade, negative = upgrade. Range -18..18.
28	export function notchChange(previous, current) {
29	  const previousIndex = ratingIndex(previous, "previous");
30	  const currentIndex = ratingIndex(current, "current");
31	  // `+ 0` turns a possible -0 into +0.
32	  return currentIndex - previousIndex + 0;
33	}
34	
35	// Ind. 13 thresholds (C2): n <= 1 -> WL 0, n === 2 -> WL 1, n >= 3 -> WL 2.
36	export function notchCalculator(previous, current) {
37	  const notches = notchChange(previous, current);
38	  const direction = notches > 0 ? "downgrade" : notches < 0 ? "upgrade" : "unchanged";
39	  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
40	  return { notches, direction, wl };
41	}
