1	// Indicator 12: country rating change WL (REQ-03-12). Pure and synchronous: no I/O, no logging, no state.
2	import { notchChange } from "../ratings/notch.mjs";
3	
4	// Ind. 12 thresholds (C6), deliberately different from the Ind. 13 calculator:
5	// n <= 0 (upgrade or unchanged) -> 0, n === 1 -> 1, n >= 2 -> 2.
6	// Validation and normalisation come from notchChange; its RangeError is not caught.
7	export function countryRatingChangeWl(previous, current) {
8	  const notches = notchChange(previous, current);
9	  if (notches <= 0) return 0;
